if($json.approved!==true) throw new Error('GitHub write requires approved=true');
const action=String($json.action_type||'').trim();
const allowed=['github_issue_create','github_issue_comment','github_file_create','github_file_update'];
if(!allowed.includes(action)) throw new Error(`Unsupported GitHub action: ${action}`);
const p=($json.payload&&typeof $json.payload==='object')?$json.payload:{};
const owner=String(p.owner||'').trim(), repo=String(p.repo||'').trim();
if(!/^[A-Za-z0-9_.-]{1,100}$/.test(owner)||!/^[A-Za-z0-9_.-]{1,100}$/.test(repo)) throw new Error('Invalid GitHub owner/repo');
const out={approved:true,request_id:String($json.request_id||''),action_type:action,owner,repo,payload:p};
if(action==='github_issue_create'){
  out.title=String(p.title||'').trim().slice(0,240); out.body=String(p.body||'');
  if(!out.title) throw new Error('title required');
}
if(action==='github_issue_comment'){
  out.issue_number=Number(p.issue_number); out.body=String(p.body||'');
  if(!Number.isInteger(out.issue_number)||out.issue_number<1||!out.body) throw new Error('issue_number and body required');
}
if(action==='github_file_create'||action==='github_file_update'){
  const path=String(p.path||'').replace(/^\/+/, '').trim();
  if(!path||path.includes('..')||path.length>500) throw new Error('Invalid path');
  out.encoded_path=path.split('/').map(encodeURIComponent).join('/');
  out.message=String(p.message||'').trim().slice(0,250);
  out.content_b64=Buffer.from(String(p.content||''),'utf8').toString('base64');
  out.branch=String(p.branch||'').trim();
  if(!out.message) throw new Error('commit message required');
  if(action==='github_file_update'){
    out.sha=String(p.sha||'').trim();
    if(!/^[0-9a-f]{40}$/i.test(out.sha)) throw new Error('40-hex current blob sha required for update');
  }
}
return [{json:out}];
